function lowerHeaders(headers) {
  const result = {};
  Object.keys(headers || {}).forEach((k) => { result[String(k).toLowerCase()] = headers[k]; });
  return result;
}
function submittedEntries(attrs) {
  const submitted = attrs.submitted_values || attrs.submittedValues || [];
  if (Array.isArray(submitted)) return submitted;
  if (submitted && typeof submitted === 'object') return Object.entries(submitted).map(([name, value]) => ({ name, value }));
  return submitted ? [{ value: submitted }] : [];
}
function submissionValue(entries) {
  const first = entries[0];
  if (!first) return '';
  if (typeof first === 'object') return first.value || first.payload || first.title || first.name || '';
  return first;
}
function formData(entries) {
  const data = {};
  entries.forEach((entry, index) => {
    if (!entry || typeof entry !== 'object') return;
    const key = entry.name || entry.id || entry.key || `field_${index + 1}`;
    if (key === '_attachment_refs') return;
    data[key] = entry.value ?? entry.answer ?? entry.text ?? '';
  });
  return data;
}
function asObject(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return value;
}
function validSupportEntryPoint(value) {
  const normalized = String(value || '').trim().toLowerCase();
  return ['main_menu', 'tournament'].includes(normalized) ? normalized : '';
}
function cleanTextAttribute(value) {
  return String(value || '').trim().slice(0, 120);
}
function cleanListAttribute(value) {
  const raw = Array.isArray(value) ? value.join(',') : String(value || '');
  return raw.split(/[,|]/).map((item) => item.trim()).filter(Boolean).slice(0, 3).join(',');
}
function attachmentMeta(attachment) {
  if (!attachment || typeof attachment !== 'object') return null;
  return {
    id: attachment.id || attachment.blob_id || null,
    message_id: attachment.message_id || null,
    file_type: attachment.file_type || null,
    extension: attachment.extension || null,
    content_type: attachment.content_type || null,
    file_size: attachment.file_size || null,
    width: attachment.width || null,
    height: attachment.height || null
  };
}
function collectAttachments(...sources) {
  const seen = new Set();
  const result = [];
  for (const source of sources) {
    const list = Array.isArray(source) ? source : [];
    for (const attachment of list) {
      const meta = attachmentMeta(attachment);
      if (!meta) continue;
      const key = [meta.id, meta.message_id, meta.file_type, meta.extension, meta.content_type, meta.file_size].map((part) => String(part || '')).join('|');
      if (seen.has(key)) continue;
      seen.add(key);
      result.push(meta);
    }
  }
  return result;
}

const root = $input.first().json;
const headers = lowerHeaders(root.headers);
const secret = $env.CHATWOOT_WEBHOOK_SECRET;
if (secret) {
  const got = headers['x-webhook-secret'] || headers['x-chatwoot-secret'];
  if (String(got || '') !== String(secret)) return [{ json: { skip: true, reason: 'bad_secret' } }];
}

const payload = root.body && typeof root.body === 'object' ? root.body : root;
const isResolvedStatusChange = payload.event === 'conversation_status_changed' && String(payload.status || '').toLowerCase() === 'resolved';
if (isResolvedStatusChange) {
  const accountId = payload.account?.id || payload.account_id || payload.messages?.[0]?.account_id;
  const conversationId = payload.id || payload.conversation?.id || payload.conversation_id;
  const deliveryId = headers['x-chatwoot-delivery'] || payload.updated_at || payload.timestamp || payload.created_at || Date.now();
  const messageId = `status:${conversationId}:${deliveryId}`;
  const customAttributes = asObject(payload.custom_attributes || payload.conversation?.custom_attributes);
  if (!accountId || !conversationId) return [{ json: { skip: true, reason: 'missing_reset_ids' } }];
  return [{ json: { skip: false, resetOnly: true, accountId, conversationId, messageId, userText: '', attachments: [], hasAttachments: false, customAttributes, rawPayload: payload } }];
}

const message = payload.message && typeof payload.message === 'object' ? payload.message : payload;
const conversation = payload.conversation || {};
const conversationCustomAttributes = asObject(conversation.custom_attributes || payload.custom_attributes);
const contentType = message.content_type || payload.content_type;
const contentAttributes = message.content_attributes || payload.content_attributes || {};
const messageSupportEntryPoint = validSupportEntryPoint(contentAttributes.support_landing_source || contentAttributes.supportEntryPoint);
const conversationSupportEntryPoint = validSupportEntryPoint(conversationCustomAttributes.support_landing_source || conversationCustomAttributes.supportEntryPoint);
const supportEntryPoint = messageSupportEntryPoint || conversationSupportEntryPoint;
const supportEntryPointSource = messageSupportEntryPoint ? 'message_content_attributes' : (conversationSupportEntryPoint ? 'conversation_custom_attributes' : '');
const messageCurrentTournamentId = cleanTextAttribute(contentAttributes.current_tournament_id || contentAttributes.currentTournamentId || contentAttributes.tournament_id || contentAttributes.tournamentId);
const conversationCurrentTournamentId = cleanTextAttribute(conversationCustomAttributes.current_tournament_id || conversationCustomAttributes.currentTournamentId || conversationCustomAttributes.tournament_id || conversationCustomAttributes.tournamentId);
const currentTournamentId = messageCurrentTournamentId || conversationCurrentTournamentId;
const messageLast3TournamentIds = cleanListAttribute(contentAttributes.last_3_tournament_ids || contentAttributes.last3TournamentIds || contentAttributes.last_tournament_ids || contentAttributes.recentTournamentIds);
const conversationLast3TournamentIds = cleanListAttribute(conversationCustomAttributes.last_3_tournament_ids || conversationCustomAttributes.last3TournamentIds || conversationCustomAttributes.last_tournament_ids || conversationCustomAttributes.recentTournamentIds);
const last3TournamentIds = messageLast3TournamentIds || conversationLast3TournamentIds;
const entries = submittedEntries(contentAttributes);
const selectedValue = submissionValue(entries);
const supportedSubmission = ['input_select', 'form'].includes(contentType) && entries.length > 0;
const hasInteractiveSubmission = payload.event === 'message_updated' && supportedSubmission;
if (payload.event !== 'message_created' && !hasInteractiveSubmission) return [{ json: { skip: true, reason: 'unsupported_event' } }];

const lastConversationMessage = Array.isArray(conversation.messages) ? (conversation.messages.find((item) => String(item.id) === String(message.id || payload.id)) || conversation.messages[0] || {}) : {};
const attachments = collectAttachments(message.attachments, payload.attachments, payload.message?.attachments, lastConversationMessage.attachments);
const hasAttachments = attachments.length > 0;
const sender = message.sender || payload.sender || payload.contact || {};
const senderType = String(sender.type || message.sender_type || payload.sender_type || message.senderType || payload.senderType || lastConversationMessage.sender_type || lastConversationMessage.sender?.type || conversation.meta?.sender?.type || (payload.contact ? 'contact' : '')).toLowerCase();
const isContact = senderType === 'contact';
const mt = message.message_type ?? payload.message_type;
const isIncoming = mt === 0 || mt === '0' || String(mt).toLowerCase() === 'incoming';
const isPrivate = message.private === true || payload.private === true;
if (isPrivate || (!hasInteractiveSubmission && (!isContact || !isIncoming))) return [{ json: { skip: true, reason: 'not_customer_incoming' } }];

const account = payload.account || {};
const inbox = payload.inbox || {};
const contact = payload.contact || ((senderType === 'contact' && sender.type) ? sender : undefined) || conversation.meta?.sender || lastConversationMessage.sender || {};
const accountId = account.id;
const conversationId = conversation.id || conversation.display_id || payload.conversation_id;
const baseMessageId = message.id || payload.id;
const deliveryId = headers['x-chatwoot-delivery'] || payload.updated_at || payload.created_at || '';
const interactiveText = contentType === 'form' ? JSON.stringify(formData(entries)) : String(selectedValue || '').trim();
const messageId = hasInteractiveSubmission ? `${baseMessageId}:${contentType}:${interactiveText}:${deliveryId}` : baseMessageId;
const userText = String(hasInteractiveSubmission ? interactiveText : (message.content || payload.content || '')).trim();
if (!accountId || !conversationId || !messageId) return [{ json: { skip: true, reason: 'missing_ids' } }];

return [{ json: { skip: false, accountId, conversationId, messageId, userText, inboxId: conversation.inbox_id || inbox.id, contactId: contact.id || conversation.contact_inbox?.contact_id || lastConversationMessage.sender_id, senderType, isInteractiveSubmission: Boolean(hasInteractiveSubmission), interactiveContentType: hasInteractiveSubmission ? contentType : null, submittedValues: entries, attachments, hasAttachments, supportEntryPoint, supportEntryPointSource, currentTournamentId, last3TournamentIds, rawPayload: payload } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessages) staticData.seenMessages = {};
if (!staticData.convDebounce) staticData.convDebounce = {};

const item = $input.first().json;
const messageId = String(item.messageId);
const convId = String(item.conversationId);
const now = Date.now();
const windowMs = Number($env.IDEMPOTENCY_WINDOW_MS || 120000);
const debounceMs = Number($env.CONVERSATION_DEBOUNCE_MS || 2000);
const isInteractiveSubmission = item.isInteractiveSubmission === true;
const isResetOnly = item.resetOnly === true;
for (const k of Object.keys(staticData.seenMessages)) {
  if (now - staticData.seenMessages[k] > windowMs) delete staticData.seenMessages[k];
}
if (staticData.seenMessages[messageId]) return [{ json: { ...item, skip: true, reason: 'duplicate_message' } }];
const last = staticData.convDebounce[convId] || 0;
if (!isInteractiveSubmission && !isResetOnly && now - last < debounceMs) return [{ json: { ...item, skip: true, reason: 'conversation_debounce' } }];
staticData.seenMessages[messageId] = now;
if (!isInteractiveSubmission && !isResetOnly) staticData.convDebounce[convId] = now;
return [{ json: { ...item, skip: false } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.failedTurns) staticData.failedTurns = {};
if (!staticData.convDebounce) staticData.convDebounce = {};

const item = $input.first().json;
const key = String(item.conversationId);
delete staticData.failedTurns[key];
delete staticData.convDebounce[key];

const currentAttributes = item.customAttributes && typeof item.customAttributes === 'object' ? item.customAttributes : {};
const currentState = currentAttributes.n8n_guided_flow && typeof currentAttributes.n8n_guided_flow === 'object' ? currentAttributes.n8n_guided_flow : {};
const resetState = {
