const additionalAttributes = conversation.additional_attributes || conversation.payload?.additional_attributes || {};
const fetchedSupportEntryPoint = validSupportEntryPoint(customAttributes.support_landing_source || customAttributes.supportEntryPoint);
const supportEntryPoint = base.supportEntryPoint || fetchedSupportEntryPoint;
const supportEntryPointSource = base.supportEntryPointSource || (fetchedSupportEntryPoint ? 'conversation_custom_attributes' : '');
const fetchedCurrentTournamentId = cleanTextAttribute(customAttributes.current_tournament_id || customAttributes.currentTournamentId || customAttributes.tournament_id || customAttributes.tournamentId || additionalAttributes.current_tournament_id || additionalAttributes.currentTournamentId || additionalAttributes.tournament_id || additionalAttributes.tournamentId);
const currentTournamentId = base.currentTournamentId || fetchedCurrentTournamentId;
