  return [{ json: { ...upstream, route: 'guided_flow', action: 'guided_reply', guidedAction: 'guided_reply', intent: target, confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: '', nextGuidedState: rendered.state, guidedMessageBody: rendered.body, privateSummary: summarize(['guided_completion_rag_continue=true', 'target=' + target, extra].filter(Boolean).join('|')), labelSuggestions: Array.from(new Set([...(agent.labels || []), 'guided_flow', 'guided_completion_rag_checked'])) } }];
}

if (isGuidedCompletionRagCheck) {
  const goodFaq = route === 'faq' && hasRetrievalProof && answer && confidence >= 0.55 && answer.length <= 900 && !risky;
  if (goodFaq) {
    const pending = {
      ...(baseState.pending_route || {}),
      rag_answer: answer,
      confidence,
      knowledge_used: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : []
    };
    const nextGuidedState = {
      ...baseState,
      mode: 'rag_resolution_check',
      step: 'awaiting_resolution_choice',
      last_action: 'guided_completion_rag_answered',
      pending_route: pending,
      updated_at: now
    };
    const guidedMessageBody = menuBody(answer + '\n\nDid this resolve your issue?', [
      { id: 'rag_resolved_yes', text: 'Yes' },
      { id: 'rag_resolved_no', text: 'No' }
    ]);
    return [{ json: { ...upstream, route: 'faq', action: 'guided_reply', guidedAction: 'guided_reply', intent: 'rag_resolution_check', confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: answer, nextGuidedState, guidedMessageBody, privateSummary: summarize('guided_completion_rag_answered=true'), labelSuggestions: Array.from(new Set([...(agent.labels || []), 'rag_answer', 'guided_completion_rag_checked'])) } }];
  }
  return continueNormalGuidedCompletion('guided_completion_rag_not_answerable=true');
}

const immediateHandoff = route === 'human_handoff' || risky || agent.needs_human === true;
if (immediateHandoff) return handoffResult();

if (route === 'guided_flow') {
  if (validStartOption?.option?.target && flow.nodes?.[validStartOption.option.target]) {
    const option = validStartOption.option;
    const parentNodeId = validStartOption.parentNodeId;
    const rendered = renderNode(option.target, {
      path: [...baseState.path, 'rag_route:' + parentNodeId, option.id],
      selected_option: option.id,
      last_action: 'rag_route_option'
    });
    if (rendered) {
      return [{ json: { ...upstream, route: 'guided_flow', action: 'guided_reply', guidedAction: 'guided_reply', intent: option.target, confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: '', nextGuidedState: rendered.state, guidedMessageBody: rendered.body, privateSummary: summarize('start_option=' + option.id + '|parent_node=' + parentNodeId + '|target=' + option.target), labelSuggestions: Array.from(new Set([...(agent.labels || []), 'guided_flow', 'rag_routed', 'rag_routed_option'])) } }];
    }
  }
  const rendered = validStartNode ? renderNode(validStartNode, { path: [...baseState.path, 'rag_route:' + validStartNode] }) : null;
  if (rendered) {
    return [{ json: { ...upstream, route: 'guided_flow', action: 'guided_reply', guidedAction: 'guided_reply', intent: validStartNode, confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: '', nextGuidedState: rendered.state, guidedMessageBody: rendered.body, privateSummary: summarize(), labelSuggestions: Array.from(new Set([...(agent.labels || []), 'guided_flow', 'rag_routed'])) } }];
  }
}

if (route === 'clarification') {
  const pending = { original_user_text: upstream.userText || '', start_node: validStartNode || upstream.routeContext?.current_node || flow.entry, rag_answerable: agent.rag_answerable === true, needs_structured_data: agent.needs_structured_data === true };
  const nextGuidedState = { ...baseState, current_node: baseState.current_node || flow.entry, mode: 'route_clarification', step: 'awaiting_route_choice', last_action: 'route_clarification', pending_route: pending, updated_at: now };
  const guidedMessageBody = menuBody(agent.clarification_prompt || 'I can answer from our help articles, or collect details so the team can look into your issue. What would you like to do?', [
    { id: 'route_answer', text: 'Show me the answer' },
    { id: 'route_issue', text: 'Help with my issue' },
    { id: 'route_human', text: 'Other' }
  ]);
  return [{ json: { ...upstream, route: 'clarification', action: 'guided_reply', guidedAction: 'guided_reply', intent: 'route_clarification', confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: '', nextGuidedState, guidedMessageBody, privateSummary: summarize(), labelSuggestions: Array.from(new Set([...(agent.labels || []), 'route_clarification'])) } }];
}

const shouldHandoff = confidence < 0.55 || (route === 'faq' && (!hasRetrievalProof || !answer || answer.length > 900));
if (shouldHandoff) {
  const markers = ['low_confidence_or_bad_faq=true'];
  if (route === 'faq' && !hasRetrievalProof) {
    markers.push('ungrounded_faq_suppressed=true');
    markers.push('knowledge_used_empty=' + (knowledgeUsed.length === 0));
  }
  return handoffResult(markers.join('|'), { suppressAnswer: route === 'faq' });
}

function previousGuidedStateForRecovery() {
  const previous = routeContext.previous_guided_state && typeof routeContext.previous_guided_state === 'object' ? routeContext.previous_guided_state : {};
  const nodeId = previous.current_node || routeContext.current_node || baseState.current_node;
  const node = nodeId && flow.nodes?.[nodeId] ? flow.nodes[nodeId] : null;
  if (!node || nodeId === flow.entry || nodeId === 'llm' || nodeId === 'human') return null;
  if (!['form', 'options', 'text'].includes(node.type)) return null;
  return {
    ...baseState,
    ...previous,
    current_node: nodeId,
    mode: previous.mode || node.type,
    step: previous.step || node.type,
    pending_route: previous.pending_route || null,
    resolved: false
  };
}
const previousGuidedState = route === 'faq' && !isGuidedCompletionRagCheck ? previousGuidedStateForRecovery() : null;
if (previousGuidedState && hasRetrievalProof && answer && confidence >= 0.55 && answer.length <= 900 && !risky) {
  const nextGuidedState = {
    ...baseState,
    current_node: previousGuidedState.current_node,
    mode: 'faq_recovery',
    step: 'awaiting_recovery_choice',
    selected_option: 'faq_recovery',
    pending_route: {
      previous_guided_state: previousGuidedState,
      faq_answer: answer,
      knowledge_used: knowledgeUsed,
      confidence
    },
    last_action: 'faq_recovery_prompted',
    resolved: false,
    updated_at: now
  };
  const guidedMessageBody = menuBody(answer + '\n\nWhat would you like to do next?', [
    { id: 'faq_continue_report', text: 'Continue my report' },
    { id: 'faq_ask_another', text: 'Ask another question' },
    { id: 'faq_main_menu', text: 'Main menu' },
    { id: 'faq_human', text: 'Other' }
  ]);
  return [{ json: { ...upstream, route: 'faq', action: 'guided_reply', guidedAction: 'guided_reply', intent: 'faq_recovery', confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: answer, nextGuidedState, guidedMessageBody, privateSummary: summarize('faq_recovery_prompted=true'), labelSuggestions: Array.from(new Set([...(agent.labels || []), 'rag_answer', 'faq_recovery'])) } }];
}

const publicAnswer = answer;
const labels = Array.from(new Set([...(agent.labels || []), 'rag_answer']));
return [{ json: { ...upstream, route: 'faq', action: 'reply', guidedAction: 'reply', intent: 'faq', confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer, privateSummary: summarize(), labelSuggestions: labels } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.failedTurns) staticData.failedTurns = {};
const item = $input.first().json;
const key = String(item.conversationId);
const failed = item.action !== 'resolve' && (item.action === 'handoff' || Number(item.confidence || 0) < 0.75);
const count = failed ? Number(staticData.failedTurns[key] || 0) + 1 : 0;
staticData.failedTurns[key] = count;
const forceHandoff = count >= Number($env.FAILED_TURN_THRESHOLD || 2);
if (forceHandoff && item.action !== 'handoff') {
  return [{ json: { ...item, action: 'handoff', privateSummary: `${item.privateSummary} | forced_handoff_after_failed_turns=${count}`, labelSuggestions: Array.from(new Set([...(item.labelSuggestions || []), 'repeated_bot_failure'])) } }];
}
return [{ json: { ...item, failedTurnCount: count } }];

const item = $input.first().json;
const now = new Date().toISOString();
const current = item.nextGuidedState || item.guidedState || {};
const cameFromLlm = item.guidedAction === 'llm' || current.mode === 'llm' || current.step === 'llm_support';
const llmTurns = Number(current.llm_turns || 0) + (cameFromLlm ? 1 : 0);
const handoff = item.action === 'handoff';
const resolved = item.action === 'resolve';
if (resolved || handoff) {
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.failedTurns) staticData.failedTurns = {};
  if (!staticData.convDebounce) staticData.convDebounce = {};
  const key = String(item.conversationId);
  delete staticData.failedTurns[key];
  delete staticData.convDebounce[key];
}
const terminal = resolved || handoff;
const nextGuidedState = terminal ? {
  flow_version: current.flow_version || item.guidedFlow?.version || 1,
  conversation_id: item.conversationId,
  current_node: null,
  path: [],
  form_data: {},
  form_attachments: {},
  pending_attachments: [],
  llm_turns: 0,
  selected_option: null,
  mode: handoff ? 'handoff' : 'completed',
  step: resolved ? 'llm_resolved' : 'handoff_active_silent',
  pending_route: null,
  last_action: resolved ? 'llm_resolved' : 'handoff_completed_silent',
  resolved,
  updated_at: now
} : {
  ...current,
  current_node: current.current_node,
  mode: 'llm',
  step: 'llm_replied',
  selected_option: current.selected_option || 'custom_question',
  llm_turns: llmTurns,
  last_action: 'llm_replied',
  resolved: false,
  updated_at: now
};
const labelSuggestions = Array.from(new Set([...(item.labelSuggestions || []), 'guided_flow', ...(resolved ? ['resolved_by_customer'] : [])]));
const privateSummary = [
  item.privateSummary || 'No summary provided by AI Agent.',
  `guided_mode=${nextGuidedState.mode}`,
  `guided_step=${nextGuidedState.step}`,
  `guided_selected=${nextGuidedState.selected_option}`,
  `llm_turns=${llmTurns}`
].join(' | ');
return [{ json: { ...item, nextGuidedState, labelSuggestions, privateSummary, failedTurnCount: item.failedTurnCount } }];

parameters.jsonBody:
={{ (() => {
  const source = $('Prepare LLM Guided State').first().json;
  function cleanSummary(value) {
    let text = String(value || '').replace(/\s+/g, ' ').trim();
    if (text.includes('|')) text = text.split('|')[0].trim();
    text = text
      .replace(/\b(route|action|intent|confidence|start_node|start_option|knowledge_used|risk_flags|guided_mode|guided_step|guided_selected|llm_turns|target|node|path|form_data|reason)=[^|]+/gi, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (!text || /^no summary provided/i.test(text) || /^rag router decision/i.test(text)) {
      text = source.action === 'resolve'
        ? 'Customer indicated the issue was resolved.'
        : 'Bot handed the conversation to the team for follow-up.';
    }
    if (text.length > 240) text = text.slice(0, 237).trim() + '...';
    return text;
  }
  return JSON.stringify({ content: 'Bot handoff: ' + cleanSummary(source.privateSummary), message_type: 'outgoing', private: true });
})() }}
